import type { ReasoningEffort } from './types';

/**
 * Bundled models.dev cards (`https://models.dev/api.json`) for providers whose own `/models`
 * listing omits the facts the picker needs. Two kinds of entry:
 *
 *  - **Authoritative** (`CATALOG_AUTHORITY`): the wire answers with ids and `owned_by` only
 *    (NVIDIA NIM, Kilo Gateway) or serves a fixed pair behind a local bridge (deepseek-chat), so
 *    the catalog IS the lineup — a live id without a card is not a chat model (embedder, safety
 *    guard, vision-only) and never reaches the picker. A listing that shares no id with the
 *    catalog is a gateway that renames its models: the whole catalog then stands.
 *
 *  - **Enriching** (the rest): the wire is the availability check and may declare some facts
 *    (OpenRouter-style `context_length`, `supported_parameters`); a declared wire fact always
 *    wins over the card, and the card fills in what the wire omits (context window, display
 *    name, effort ladder). A live id the snapshot does not know keeps its wire-only row.
 *
 * Regenerate with the generator in the session temp folder when a provider adds a model; the
 * `deepseek-chat` block at the end is hand-written, so it survives regeneration.
 */
export interface CatalogModel {
  id: string;
  /** Display name from models.dev; a raw id is never shown when a card exists. */
  name: string;
  /** Input window in tokens; the context ring and the context guard need it. */
  context?: number;
  /** Declared output cap in tokens. */
  output?: number;
  /** Whether the endpoint accepts tool definitions (models.dev `tool_call`). */
  tools: boolean;
  /** Whether the endpoint accepts image parts (models.dev input modalities). */
  images?: boolean;
  /**
   * Effort levels the endpoint accepts, least first (models.dev `reasoning_options`). Absent
   * means the model has no reasoning knob, so the selector is not offered for it.
   */
  efforts?: ReasoningEffort[];
}

